INSERT INTO question_bank_2_examples (id, group_id, content, sequence)
VALUES (
  '1bf6a2d5-84f3-530d-b2a2-b620ba8f0224', 'bce3226a-de1e-5ea2-b32d-9d3edab29bae',
  'The relationship between a group of people is represented by an adjacency-list friends. If `friends[u]` contains `v`, `u` and `v` are friends. Friendship is a two-way relationship. Two people are in a friend group as long as there is some path of mutual friends connecting them.

Request: Implement function:

```cpp
int numberOfFriendGroups(vector<vector<int>>& friends);
```

Where `friends` is the adjacency-list representing the friendship (this list has between 0 and 1000 lists).

This function returns the number of friend groups.

Example: Given an adjacency-list: `[[1], [0, 2], [1], [4], [3], []]`, there are 3 friend groups:

- `[0, 1, 2]`
- `[3, 4]`
- `[5]`

Note: In this exercise, the libraries `iostream`, `string`, `cstring`, `climits`, `utility`, `vector`, `list`, `stack`, `queue`, `map`, `unordered_map`, `set`, `unordered_set`, `functional`, and `algorithm` have been included and namespace `std` is used. You can write helper functions and classes. Importing other libraries is allowed, but not encouraged.', 26
);

INSERT INTO question_bank_2_examples (id, group_id, content, sequence)
VALUES (
  '4cab4362-c3b8-5175-a70a-1cc5084526b8', 'bce3226a-de1e-5ea2-b32d-9d3edab29bae',
  'Implement function to detect a cyclic in Graph.

```cpp
#include <iostream>
#include <vector>
#include <list>
using namespace std;

class DirectedGraph
{
    int V;
    vector<list<int>> adj;
public:
    DirectedGraph(int V)
    {
        this->V = V;
        adj = vector<list<int>>(V, list<int>());
    }
    void addEdge(int v, int w)
    {
        adj[v].push_back(w);
    }
    bool isCyclic()
    {
